const paths={message:'<path d="M5 3h14a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3H9l-7 4V6a3 3 0 0 1 3-3Z"/><path d="M7 10h.1M12 10h.1M17 10h.1"/>',bell:'<path d="M5 16c2-2 1-4 2-8a5 5 0 0 1 10 0c1 4 0 6 2 8l1 2H4l1-2ZM10 21q2 2 4 0M12 2V1"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 22v-3a7 7 0 0 1 14 0v3ZM17 4a4 4 0 0 1 0 8M19 16q4 1 4 6h-4"/>',calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M3 10h18M7 1v6M17 1v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',alert:'<path d="m12 3 10 18H2L12 3ZM12 9v5M12 17h.1"/>',chevron:'<path d="m9 5 7 7-7 7"/>',trend:'<path d="m2 4 8 8 5-5 7 12M15 19h7v-7"/>',note:'<path d="M16 2H5a2 2 0 0 0-2 2v17a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V7l-5-5ZM15 2v6h6M7 12h10M7 17h7M7 7h4"/>',renew:'<path d="M21 9a9 9 0 1 0-1 10M21 3v6h-6"/>',user:'<circle cx="12" cy="6" r="4"/><path d="M4 23v-2a8 8 0 0 1 16 0v2"/>',home:'<path d="m3 10 9-8 9 8v12h-6v-8H9v8H3Z"/>',check:'<rect x="2" y="2" width="20" height="20" rx="3" fill="currentColor"/><path d="m6 12 4 4 8-9" stroke="#151515" stroke-width="2"/>',play:'<circle cx="12" cy="12" r="11"/><path class="play-triangle" d="m10 8 6 4-6 4Z"/>',dumbbell:'<rect x="4" y="5" width="4" height="14" rx="1"/><rect x="16" y="5" width="4" height="14" rx="1"/><path d="M8 12h8M2 9v6M22 9v6"/>'};
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[el.dataset.icon]||''}</svg>`);
// Layout is responsive CSS; no viewport scaling is applied.

const panel=document.getElementById('panel'),title=document.getElementById('panel-title'),body=document.getElementById('panel-body');const members=[{name:'田中 健',time:'10:00',focus:'胸・上腕三頭筋',count:'18 / 24回'},{name:'佐藤 由紀',time:'11:30',focus:'お尻・脚',count:'6 / 16回'},{name:'王 明',time:'15:00',focus:'脂肪燃焼',count:'11 / 24回'}];
const alertData=[['ベンチプレスの記録が低下','直近3回のセッションで記録が低下しています。次回のセッションでフォーム、疲労感、負荷設定を確認しましょう。'],['食事の記録が未提出','7日間、食事の投稿がありません。次回の面談時に、食事記録の状況を確認しましょう。'],['パーソナルトレーニング残り3回','継続の目標とご希望を確認して、次のプランをご案内しましょう。']];
function show(t,html){title.textContent=t;body.innerHTML=html;if(!panel.open)panel.showModal();}function row(a,b){return `<div class="detail-row">${a}<small>${b}</small></div>`}function notify(t){panel.close();const el=document.getElementById('toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',2600);}document.getElementById('close').onclick=()=>panel.close();panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)panel.close();}});
function member(i){const m=members[i];show(m.name,row('本日のセッション',m.time+' · 60分')+row('トレーニング内容',m.focus)+row('ご利用状況',m.count)+`<button class="primary" data-begin="${i}">セッションを開始</button>`)}
const actions={home:()=>panel.close(),members:()=>show('担当会員',members.map((m,i)=>`<button class="detail-row" style="display:block;width:100%;text-align:left" data-member="${i}">${m.name}<small>${m.focus} · ${m.count}</small></button>`).join('')+'<p>ホームに表示されている会員です。</p>'),sessions:()=>show('今日のセッション',members.map((m,i)=>`<button class="detail-row" style="display:block;width:100%;text-align:left" data-member="${i}">${m.time}　${m.name}<small>60分 · ${m.focus}</small></button>`).join('')+'<p>本日の8件のうち、ホームに表示されている3件です。</p>'),notifications:()=>show('フォローが必要な会員',alertData.map((a,i)=>`<button class="detail-row" style="display:block;width:100%;text-align:left" data-alert="${i}">${a[0]}<small>詳細を確認 →</small></button>`).join('')),checkins:()=>show('チェックイン確認',row('6件のチェックインが確認待ち','会員のチェックイン内容を確認するには、実際の会員データとの接続が必要です。')),start:()=>show('セッションを開始',members.map((m,i)=>`<button class="primary" data-begin="${i}">${m.time}　${m.name}</button>`).join('')),notes:()=>{show('会員メモ','<label for="memo">この端末にメモを保存</label><textarea id="memo" placeholder="セッションの気づきや、次回の確認事項を入力"></textarea><button class="primary" id="save-note">メモを保存</button>');try{document.getElementById('memo').value=localStorage.getItem('gyme-note')||''}catch{}document.getElementById('save-note').onclick=()=>{try{localStorage.setItem('gyme-note',document.getElementById('memo').value);notify('メモをこの端末に保存しました')}catch{notify('保存できませんでした')}}},renewals:()=>show('プラン更新',row('継続プランのご案内','パーソナルトレーニングが残り3回の会員がいます。')+'<p>更新手続きには会員データとの接続が必要です。</p>'),messages:()=>show('メッセージ','<p>会員とのメッセージをここで確認できます。</p><p>メッセージの取得・送信にはデータ接続が必要です。</p>'),profile:()=>show('プロフィール',row('健太','Gyme トレーナー')+row('担当会員','24名'))};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'),m=e.target.closest('[data-member]'),al=e.target.closest('[data-alert]'),begin=e.target.closest('[data-begin]');if(a)actions[a.dataset.action]?.();if(m)member(Number(m.dataset.member));if(al){const d=alertData[Number(al.dataset.alert)];show(d[0],`<p>${d[1]}</p>`)}if(begin){const m=members[Number(begin.dataset.begin)];show('セッション中',row(m.name,m.focus)+row('予定時間','60分')+'<p>この画面内でセッションを開始しました。</p><button class="primary" id="finish">セッションを終了</button>');document.getElementById('finish').onclick=()=>notify('セッションを終了しました')}});
